const TOKEN = "YOUR_AIRTABLE_PERSONAL_ACCESS_TOKEN";
const BASE = "YOUR_AIRTABLE_BASE_ID";
const TABLE = "YOUR_AIRTABLE_LEADS_TABLE_ID";

// META 24h messaging window (J+0): ONLY contact clients who sent a message in the last 24 hours.
// Sending outside this window risks Meta account bans.
// Also: no RDV yet, ACTIVE, has sender_id, <3 followups total,
// and we have not already followed-up since their last inbound message.
const formula = "AND(" +
  "OR({appointment_id} = '', {appointment_id} = BLANK()), " +
  "OR({status} = 'ACTIVE', {status} = BLANK()), " +
  "NOT({status} = 'STOP'), " +
  "{sender_id} != '', " +
  "{last_message_at} != '', " +
  "NOT({last_message_at} = BLANK()), " +
  "DATETIME_DIFF(NOW(), {last_message_at}, 'hours') < 24, " +
  "OR({followup_count} = BLANK(), {followup_count} < 3), " +
  "OR({last_followup_at} = BLANK(), IS_BEFORE({last_followup_at}, {last_message_at}))" +
  ")";

const out = [];
let offset = '';
do {
  const qs = {
    filterByFormula: formula,
    pageSize: 100,
  };
  if (offset) qs.offset = offset;
  const res = await this.helpers.httpRequest({
    method: 'GET',
    url: `https://api.airtable.com/v0/${BASE}/${TABLE}`,
    qs,
    headers: { Authorization: 'Bearer ' + TOKEN },
    json: true,
    timeout: 30000,
  });
  const records = (res && res.records) || [];
  for (const r of records) {
    const f = r.fields || {};
    const lastMsg = String(f.last_message_at || '').trim();
    // Defense in depth: re-check 24h window in JS (Airtable NOW() timezone edge cases)
    if (lastMsg) {
      const t = Date.parse(lastMsg);
      if (!Number.isFinite(t) || (Date.now() - t) >= 24 * 60 * 60 * 1000) continue;
    } else {
      continue;
    }
    out.push({
      json: {
        id: r.id,
        ...f,
        sender_id: f.sender_id || '',
        senderId: f.sender_id || '',
        followup_count: Number(f.followup_count || 0) || 0,
        channel: f.channel || '',
        langue: f.langue || 'FR',
        prenom: f.prenom || '',
        prestation: f.prestation || '',
        historique: f.historique || '',
        status: f.status || 'ACTIVE',
        appointment_id: f.appointment_id || '',
        last_followup_at: f.last_followup_at || '',
        last_message_at: lastMsg,
        metaWindowOk: true,
      },
    });
  }
  offset = (res && res.offset) || '';
} while (offset);

return out;

const items = $input.all();
function normLang(raw) {
  const x = String(raw || 'FR').trim();
  if (/^en/i.test(x)) return 'EN';
  if (/^ar/i.test(x)) return 'AR';
  if (/darija/i.test(x)) return 'darija';
  return 'FR';
}

const out = [];
for (const item of items) {
  const j = item.json || {};
  const status = String(j.status || '').trim().toUpperCase();
  if (status === 'STOP') continue;

  const senderId = String(j.sender_id || j.senderId || '').trim();
  if (!senderId) continue;


  // Meta 24h window — never enqueue outside customer care window
  const lastMsgAt = String(j.last_message_at || '').trim();
  if (!lastMsgAt) continue;
  const lastMsgMs = Date.parse(lastMsgAt);
  if (!Number.isFinite(lastMsgMs) || (Date.now() - lastMsgMs) >= 24 * 60 * 60 * 1000) continue;
  // Skip if already booked
  if (String(j.appointment_id || '').trim()) continue;

  const lang = normLang(j.langue);
  const prenom = j.prenom || '';
  const hist = String(j.historique || '').slice(-1500);
  const prestation = j.prestation || '';
  const channel = String(j.channel || '').toLowerCase();

  const prompt =
    'You are YOUR_ASSISTANT_NAME, the booking assistant for YOUR_BUSINESS_NAME.\n' +
    'Ecris un court message de suivi (2-3 phrases max, 1 emoji max) pour relancer une cliente qui a ecrit mais n\'a PAS encore reserve.\n' +
    'LANGUE: ' + lang + ' uniquement.\n' +
    'Ton: professionnel, chaleureux, humain.\n' +
    'Rappelle poliment que tu restes dispo pour tarifs / creneaux / reservation.\n' +
    'Ne dis PAS que c\'est reserve. Pas de lien cal.com obligatoire.\n' +
    'Prenom: ' + (prenom || '(inconnu)') + '\n' +
    'Prestation: ' + (prestation || '(inconnue)') + '\n' +
    'Historique recent:\n' + (hist || '(vide)') + '\n\n' +
    'Ecris UNIQUEMENT le message final a envoyer.';

  out.push({
    json: {
      ...j,
      senderId,
      channel,
      langue: lang,
      groqPrompt: prompt,
      followup_count: Number(j.followup_count || 0),
      airtableId: j.id || j.recordId || '',
    },
  });
}

if (!out.length) {
  // No candidates — stop branch quietly
  return [];
}
return out;

const builds = $('Build Follow-Up Prompt').all();
const raws = $input.all();

return raws.map((item, i) => {
  const raw = item.json || {};
  const ctx = (builds[i] && builds[i].json) || (builds[0] && builds[0].json) || {};
  // Claude Messages API
  let text = '';
  if (Array.isArray(raw.content)) {
    text = String((raw.content.find((c) => c && c.type === 'text') || {}).text || '').trim();
  }
  // OpenAI/OpenRouter fallback (legacy)
  if (!text) text = String(raw.choices?.[0]?.message?.content || '').trim();
  if (!text) {
    const lang = String(ctx.langue || 'FR').toUpperCase();
    text = lang === 'EN'
      ? ('Hi' + (ctx.prenom ? (' ' + ctx.prenom) : '') + '! Just checking in — still happy to help you book a YOUR_BUSINESS_NAME session when you are ready.')
      : ('Bonjour' + (ctx.prenom ? (' ' + ctx.prenom) : '') + ' ! Je me permets un petit message — je reste dispo pour vous aider a reserver votre seance YOUR_BUSINESS_NAME quand vous voulez.');
  }
  text = text.replace(/https?:\/\/cal\.com\/\S+/gi, '').trim();
  if (text.length > 450) text = text.slice(0, 447) + '...';
  return {
    json: {
      ...ctx,
      finalResponse: text,
      llmRawOk: !!(Array.isArray(raw.content) && raw.content.length) || !!(raw.choices?.[0]?.message?.content),
    },
  };
});

const TOKEN = "YOUR_AIRTABLE_PERSONAL_ACCESS_TOKEN";
const BASE = "YOUR_AIRTABLE_BASE_ID";
const TABLE = "YOUR_AIRTABLE_LEADS_TABLE_ID";

const items = $input.all();
const out = [];

for (const item of items) {
  const j = item.json || {};
  const senderId = String(j.senderId || j.sender_id || '').trim();
  if (!senderId) {
    out.push({ json: { ...j, airtableFollowUpOk: false, airtableError: 'missing_sender_id' } });
    continue;
  }

  const nextCount = (Number(j.followup_count || 0) || 0) + 1;
  const nowIso = new Date().toISOString();

  // Find record by sender_id
  let recordId = String(j.id || j.airtableId || '').trim();
  if (!recordId) {
    const formula = `{sender_id} = '${senderId.replace(/'/g, "\\'")}'`;
    const found = await this.helpers.httpRequest({
      method: 'GET',
      url: `https://api.airtable.com/v0/${BASE}/${TABLE}`,
      qs: { filterByFormula: formula, maxRecords: 1 },
      headers: { Authorization: 'Bearer ' + TOKEN },
      json: true,
      timeout: 20000,
    });
    recordId = (((found || {}).records || [])[0] || {}).id || '';
  }

  if (!recordId) {
    out.push({ json: { ...j, airtableFollowUpOk: false, airtableError: 'record_not_found' } });
    continue;
  }

  try {
    const patched = await this.helpers.httpRequest({
      method: 'PATCH',
      url: `https://api.airtable.com/v0/${BASE}/${TABLE}/${recordId}`,
      headers: {
        Authorization: 'Bearer ' + TOKEN,
        'Content-Type': 'application/json',
      },
      body: {
        fields: {
          followup_count: nextCount,
          last_followup_at: nowIso,
        },
      },
      json: true,
      timeout: 20000,
    });
    out.push({
      json: {
        ...j,
        id: recordId,
        followup_count: nextCount,
        last_followup_at: nowIso,
        airtableFollowUpOk: true,
        airtablePatchedId: (patched && patched.id) || recordId,
      },
    });
  } catch (e) {
    out.push({
      json: {
        ...j,
        airtableFollowUpOk: false,
        airtableError: String((e && e.message) || e).slice(0, 300),
      },
    });
  }
}

return out;

// BUYER SETUP: replace this map with your own Cal.com event type slugs and durations.
const CAL_LINKS = {
  service_1: 'https://cal.com/YOUR_CAL_USERNAME/YOUR_EVENT_TYPE_1',
  service_2: 'https://cal.com/YOUR_CAL_USERNAME/YOUR_EVENT_TYPE_2',
  consultation: 'https://cal.com/YOUR_CAL_USERNAME/YOUR_CONSULTATION_EVENT_TYPE',
};
const CAL_PACK_MAP = {
  service_1: {
    standard: { slug: 'YOUR_EVENT_TYPE_1_STANDARD', link: CAL_LINKS.service_1, durationMin: 60 },
    premium: { slug: 'YOUR_EVENT_TYPE_1_PREMIUM', link: CAL_LINKS.service_1, durationMin: 90 },
  },
  service_2: {
    standard: { slug: 'YOUR_EVENT_TYPE_2_STANDARD', link: CAL_LINKS.service_2, durationMin: 60 },
  },
  consultation: {
    default: { slug: 'YOUR_CONSULTATION_EVENT_TYPE', link: CAL_LINKS.consultation, durationMin: 30 },
  },
};
const CAL_SESSION_FALLBACK = {
  service_1: { slug: 'YOUR_EVENT_TYPE_1_STANDARD', link: CAL_LINKS.service_1, durationMin: 60 },
  service_2: { slug: 'YOUR_EVENT_TYPE_2_STANDARD', link: CAL_LINKS.service_2, durationMin: 60 },
  consultation: { slug: 'YOUR_CONSULTATION_EVENT_TYPE', link: CAL_LINKS.consultation, durationMin: 30 },
  unknown: { slug: 'YOUR_DEFAULT_EVENT_TYPE', link: 'https://cal.com/YOUR_CAL_USERNAME/YOUR_DEFAULT_EVENT_TYPE', durationMin: 60 },
};

function resolveCalPack(prestation, packName) {
  const service = String(prestation || 'unknown').toLowerCase();
  const pack = String(packName || '').toLowerCase().trim();
  const packs = CAL_PACK_MAP[service] || {};
  if (pack && packs[pack]) return { ...packs[pack], prestation: service, packName: pack, needsPack: false };
  const fallback = CAL_SESSION_FALLBACK[service] || CAL_SESSION_FALLBACK.unknown;
  const needsPack = Object.keys(packs).filter((key) => key !== 'default').length > 1 && !pack;
  return { ...fallback, prestation: service, packName: pack, needsPack };
}

const SESSION_DURATION_MIN = { service_1: 60, service_2: 60, consultation: 30, default: 60 };

const STYLE_GUIDE = {
  FR: 'Voix de YOUR_ASSISTANT_NAME : chaleureux, simple, premium. 2-3 phrases MAX. Vouvoiement. 1 emoji max. Pas de pavé ni listes longues. Direct et humain.',
  EN: 'YOUR_ASSISTANT_NAME voice: warm, simple, premium. 2-3 sentences MAX. One emoji max. No long paragraphs.',
  AR: 'صوت سكينة: دافئ وبسيط وأنيق. جملتان أو ثلاث كحد أقصى. إيموجي واحد فقط.',
  darija: 'YOUR_ASSISTANT_NAME b darija: دافي، بسيط، طبيعي. جملتين بزاف بزاف. إيموجي واحد.'
};

const FEW_SHOT = {
  FR: 'Bonjour ! Merci pour votre message. Le 20 juillet a 10h est disponible pour votre seance. Envoyez-moi votre prenom et email pour que je reserve.',
  EN: 'Hi! Thanks for your message. July 20 at 10:00 is available for your session. Send me your first name and email and I will book it.',
  AR: 'مرحبا! شكرا على رسالتك. الموعد متاح. أرسلي الاسم والإيميل لأحجز لك.',
  darija: 'Marhba! Chokran. L creneau disponible. 3tini smiya w email bach nreservi.'
};

const CATALOGUE_TEXT = 'BUYER SETUP: add your catalog in the Get_catalogue tool.';
const PRICING_INFO = {};
const EVENEMENT_INFO = 'BUYER SETUP: add your event policy.';

const input = $input.first().json;
const body = input.body ?? input;

let channel = 'unknown';
let senderId = '';
let igUserId = '';
let messageText = '';
let messageType = 'text';
let source = 'unknown';
let mediaId = '';
let mediaUrl = '';
let audioMimeType = 'audio/ogg';

if (body.channel && body.messageText && !body.object) {
  channel = body.channel;
  senderId = String(body.senderId || 'test_user');
  messageText = String(body.messageText).trim();
  messageType = body.messageType || 'text';
  source = 'test';
} else if (body.object === 'instagram' || body.object === 'page') {
  source = 'instagram';
  channel = 'instagram';
  const entry = body.entry?.[0] || {};
  const changeVal = entry.changes?.[0]?.value;
  let msg = entry.messaging?.[0] || changeVal?.messages?.[0] || null;
  if (!msg && changeVal?.message) msg = changeVal;
  if (!msg) return [];
  if (msg.message?.is_echo) return [];
  senderId = msg.sender?.id || msg.from?.id || msg.from || '';
  // Some Instagram webhook events put the business page in sender and the client in recipient.
  // If sender is the YOUR_BUSINESS_NAME IG business ID, use recipient as the real client IGSID.
  const recipientId = msg.recipient?.id || changeVal?.recipient?.id || '';
  if (String(senderId) === 'YOUR_INSTAGRAM_ACCOUNT_ID' && recipientId) senderId = String(recipientId);
  // Keep numeric IGSID for Graph send; username resolved later for Airtable sender_id
  igUserId = String(senderId || '');
  // Some IG webhook payloads already include username
  var hookUser = String(
    msg.sender?.username ||
    msg.from?.username ||
    changeVal?.from?.username ||
    changeVal?.contacts?.[0]?.profile?.username ||
    ''
  ).replace(/^@/, '').trim();
  if (hookUser && !/^\d+$/.test(hookUser)) {
    senderId = hookUser; // provisional; Apply IG Username will confirm
  }
  const igAttachments = msg.message?.attachments || msg.attachments || changeVal?.attachments || [];
  const igAudio = Array.isArray(igAttachments)
    ? igAttachments.find(a => /audio|voice/i.test(String(a?.type || a?.mime_type || '')) || a?.payload?.url || a?.payload?.id)
    : null;
  if (msg.message?.text) messageText = msg.message.text.trim();
  else if (msg.text?.body) messageText = msg.text.body.trim();
  else if (igAudio || msg.audio || msg.voice) {
    messageType = 'audio';
    messageText = '[audio]';
    const payload = igAudio?.payload || {};
    mediaId = String(payload.id || payload.media_id || payload.attachment_id || igAudio?.id || msg.audio?.id || msg.voice?.id || '').trim();
    mediaUrl = String(payload.url || igAudio?.url || msg.audio?.url || msg.voice?.url || '').trim();
    audioMimeType = igAudio?.mime_type || msg.audio?.mime_type || msg.voice?.mime_type || 'audio/ogg';
  } else return [];
} else if (body.object === 'whatsapp_business_account') {
  source = 'whatsapp_webhook';
  channel = 'whatsapp';
  const change = body.entry?.[0]?.changes?.[0];
  const field = change?.field || '';
  const value = change?.value;
  if (!value) return [];
  if (field === 'history' || field === 'smb_app_state_sync') return [];
  if (value.statuses && !value.messages && !value.smb_message_echoes) return [];
  if (value.smb_message_echoes?.[0]) {
    const echo = value.smb_message_echoes[0];
    const store = $getWorkflowStaticData('global');
    if (!store.clients) store.clients = {};
    const sid = echo.to || echo.from || '';
    const text = echo.text?.body || (echo.type === 'audio' ? '[audio]' : '[media]');
    const c = store.clients[sid] || {};
    store.clients[sid] = {
      ...c,
      channel: 'whatsapp',
      history: ((c.history ? c.history + ' | ' : '') + 'YOUR_ASSISTANT_NAME (app): ' + text).slice(-2000),
      updatedAt: new Date().toISOString(),
    };
    return [];
  }
  if (!value.messages?.[0]) return [];
  const msg = value.messages[0];
  senderId = msg.from || '';
  if (msg.type === 'text') messageText = (msg.text?.body || '').trim();
  else if (msg.type === 'interactive') {
    messageText = (msg.interactive?.button_reply?.title || msg.interactive?.list_reply?.title || '').trim();
  } else if (msg.type === 'image' && msg.image?.caption) {
    messageText = msg.image.caption.trim();
  } else if (msg.type === 'audio' || msg.type === 'voice' || msg.audio || msg.voice) {
    messageType = 'audio';
    messageText = '[audio]';
    mediaId = String(msg.audio?.id || msg.voice?.id || msg.audio?.media_id || msg.voice?.media_id || '').trim();
    mediaUrl = String(msg.audio?.url || msg.voice?.url || '').trim();
    audioMimeType = msg.audio?.mime_type || msg.voice?.mime_type || 'audio/ogg';
  } else return [];
} else {
  return [];
}

if (!senderId) return [];
if (messageType !== 'audio' && !messageText) return [];

const lower = messageText.toLowerCase();
const botPatterns = ['sent from meta', 'message automatique', 'auto-reply', 'réponse automatique'];
const spamPatterns = ['click here', 'buy now', 'free offer', 'crypto', 'invest now'];
if (botPatterns.some((p) => lower.includes(p))) return [];
const shared = { CAL_LINKS, CAL_PACK_MAP, CAL_SESSION_FALLBACK, STYLE_GUIDE, FEW_SHOT, PRICING_INFO, CATALOGUE_TEXT, EVENEMENT_INFO, SESSION_DURATION_MIN, timestamp: new Date().toISOString() };
if (spamPatterns.some((p) => lower.includes(p))) {
  return [{ json: { channel, senderId, igUserId: (typeof igUserId !== 'undefined' ? igUserId : (channel === 'instagram' ? String(senderId) : '')), messageText, messageType, mediaId, mediaUrl, url: mediaUrl, audioMimeType, source, intention: 'spam', filtered: true, ...shared } }];
}

return [{ json: { channel, senderId, igUserId: (typeof igUserId !== 'undefined' ? igUserId : (channel === 'instagram' ? String(senderId) : '')), instagramUsername: (typeof hookUser !== 'undefined' && hookUser && !/^\d+$/.test(hookUser) ? hookUser : ''), messageText, messageType, mediaId, mediaUrl, url: mediaUrl, audioMimeType, source, filtered: false, ...shared } }];

const n = $('Normalize & Filter').first().json;
const WA_TOKEN = "YOUR_META_ACCESS_TOKEN";
const PAGE_TOKEN = "YOUR_META_ACCESS_TOKEN";
// MUST match Send WhatsApp token — old Prepare token caused graph Authentication Error
const metaToken = (n.channel === 'instagram') ? PAGE_TOKEN : WA_TOKEN;
return [{ json: {
  ...n,
  metaToken,
  mediaId: String(n.mediaId || '').trim(),
  _waToken: WA_TOKEN,
  _pageToken: PAGE_TOKEN,
} }];

const prep = $('Prepare Audio Meta').first().json;
const ready = (() => { try { return $('Resolve Media URL').first().json; } catch (e) { return {}; } })();
const raw = $input.first().json || {};
const text = String(raw.text || raw.transcript || '').trim();
const base = { ...prep, ...ready };
if (!text) {
  return [{ json: {
    ...base,
    messageText: '',
    messageType: 'text',
    transcriptionFailed: true,
    audioError: String((raw.error && (raw.error.message || JSON.stringify(raw.error))) || base.audioError || 'empty_transcript').slice(0, 500),
  } }];
}
return [{ json: {
  ...base,
  text,
  messageText: text,
  messageType: 'text',
  transcriptionFailed: false,
  fromAudio: true,
  audioError: '',
} }];

const j = $input.first().json || {};
const replies = {
  FR: 'Bonjour 🎤 Pouvez-vous me l écrire en texte s il vous plaît ?',
  EN: 'Hello 🎤 Could you please type your message in text?',
  AR: 'مرحبا 🎤 هل يمكنك كتابة رسالتك من فضلك؟',
  darija: 'Salam 🎤 wach tqderi tkteb liya message f texte?',
};
const lang = j.langue || 'FR';
const reply = replies[lang] || replies.FR;
const err = String(j.audioError || '').trim();
// Temporary debug suffix so we see WHY STT failed (remove later)
const debug = err ? (' [' + err.slice(0, 80) + ']') : '';
return [{ json: {
  ...j,
  messageText: '[audio]',
  messageType: 'text',
  audioFallback: true,
  finalResponse: reply + debug,
  escalated: false,
  escalade_requise: false,
  intention: 'autre',
} }];

const p = $input.first().json;
const store = $getWorkflowStaticData('global');
if (!store.clients) store.clients = {};
// Instagram: memory keyed by stable igUserId; CRM senderId may be username
const memKey = p.igUserId || p.senderId;
const c = store.clients[memKey] || store.clients[p.senderId] || store.clients[p.igUserId] || {};
if (p.instagramUsername && !c.instagramUsername) c.instagramUsername = p.instagramUsername;

const history = c.history || '';
const conversationContext = history
  ? ('[Historique conversation]\n' + history + '\n[Nouveau message client]\n' + p.messageText)
  : String(p.messageText || '');

const analyzeSystem = 'Tu es un classifieur JSON pour le chatbot studio photo YOUR_BUSINESS_NAME. Reponds UNIQUEMENT avec un objet JSON valide, sans markdown ni texte autour.';

const analyzeUser =
  'Analyse cette conversation cliente YOUR_BUSINESS_NAME (studio photo YOUR_BUSINESS_CITY).\n' +
  'Retourne un JSON avec les cles:\n' +
  '- intention: tarif | reservation | annulation | reschedule | evenement | reclamation | spam | autre\n' +
  '- langue: FR | EN | AR | darija\n' +
  '- sentiment: positif | neutre | negatif\n' +
  '- urgence: haute | normale\n' +
  '- prestation: grossesse | newborn | cake_smash | famille | inconnu\n' +
  '- prenom: string\n' +
  '- heure_demandee: number ou null\n' +
  '- jour_demande: string\n' +
  '- escalade_requise: boolean\n\n' +
  'Regles langue: dernier message client. Anglais=EN, Francais=FR, arabe litteraire=AR, darija marocaine=darija.\n' +
  'ESCALADE (STRICT): escalade_requise=true UNIQUEMENT si insulte, plainte service, ou hors sujet total (bitcoin, politique...). Questions prix/offres/packs/reservation/annulation/report en FR, EN, AR ou darija (ex: chno les offres, bghit ndir reservation, شحال, how much) → escalade_requise=false TOUJOURS. Ne jamais escalader faute de comprendre la langue.\nSi plainte / mecontentement / j aime pas / mauvais service → intention=reclamation et escalade_requise=true.\n' +
  'Si insulte ou hors studio → escalade_requise=true.\n' +
  'Si annule/cancel → intention=annulation.\n' +
  'Si report/replanifier/reschedule/reprogrammer/décaler/changer mon rdv → intention=reschedule (meme si le message contient demain/jour/heure).\n' +
  'Si nouvelle reservation (sans report) avec jour/heure → intention=reservation.\n' +
  'Pour un report "de X pour Y" / "pour X pour Y", jour_demande = DESTINATION (Y), pas la date actuelle (X).\n\n' +
  'Conversation:\n' + conversationContext;

const openRouterAnalyzePayload = {
  model: 'llama-3.1-8b-instant',
  messages: [
    { role: 'system', content: analyzeSystem },
    { role: 'user', content: analyzeUser },
  ],
  temperature: 0.1,
  max_tokens: 300,
};

return [{ json: {
  ...p,
  history,
  storedLangue: c.langue || '',
  lastIntention: c.lastIntention || '',
  lastPrestation: c.lastPrestation || '',
  lastPackName: c.lastPackName || c.packName || c.pack || '',
  packName: c.packName || c.lastPackName || c.pack || '',
  pack: c.pack || c.packName || c.lastPackName || '',
  _askEnfants: !!c._askEnfants,
  _askEnfantDob: !!c._askEnfantDob,
  enfantPrenoms: Array.isArray(c.enfantPrenoms) ? c.enfantPrenoms : [],
  storedPrenom: c.prenom || '',
  pendingSlot: c.pendingSlot || '',
