async function resolveInstagramUsername(igUserId, hints) {
  // Keep in sync with send dm / Fetch IG Username Page token
  const PAGE_TOKEN = "YOUR_META_ACCESS_TOKEN";
  const PAGE_ID = "YOUR_META_PAGE_ID";
  const id = String(igUserId || '').trim();
  function cleanUser(u) {
    const s = String(u || '').replace(/^@/, '').trim();
    if (!s) return '';
    if (/^\d{8,}$/.test(s)) return '';
    return s;
  }
  let username = cleanUser(hints && (hints.instagramUsername || hints.username || hints.senderId));
  if (username) return { username, igUserId: id, via: 'hint' };
  if (!id || !/^\d{5,}$/.test(id)) return { username: '', igUserId: id, via: 'no_igsid' };

  // 1) User Profile API (works for any user who messaged the business)
  try {
    const res = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://graph.facebook.com/v21.0/' + id + '?fields=username,name,id',
      headers: { Authorization: 'Bearer ' + PAGE_TOKEN },
      json: true,
      timeout: 12000,
    });
    username = cleanUser(res && res.username);
    if (username) return { username, igUserId: id, name: res.name || '', via: 'profile' };
  } catch (e) {}

  // 2) Conversations participants
  try {
    const res = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://graph.facebook.com/v21.0/' + PAGE_ID + '/conversations',
      qs: { platform: 'instagram', user_id: id, fields: 'participants', limit: 1 },
      headers: { Authorization: 'Bearer ' + PAGE_TOKEN },
      json: true,
      timeout: 12000,
    });
    const parts = (((res || {}).data || [])[0] || {}).participants || {};
    const arr = parts.data || [];
    for (const p of arr) {
      if (String(p.id) === String(id)) {
        username = cleanUser(p.username);
        if (username) return { username, igUserId: id, via: 'conversations' };
      }
    }
    for (const p of arr) {
      username = cleanUser(p.username);
      if (username && String(p.id) !== String(PAGE_ID) && String(p.id) !== 'YOUR_INSTAGRAM_ACCOUNT_ID') {
        return { username, igUserId: id, via: 'conversations_other' };
      }
    }
  } catch (e) {}

  return { username: '', igUserId: id, via: 'failed' };
}


const j = $input.first().json || {};
const TOKEN = "YOUR_AIRTABLE_PERSONAL_ACCESS_TOKEN";
const BASE = "YOUR_AIRTABLE_BASE_ID";
const TABLE = "YOUR_AIRTABLE_LEADS_TABLE_ID";

function s(v, max) {
  const t = v == null ? '' : String(v);
  return max ? t.slice(0, max) : t;
}
function boolStr(v) {
  return v === true || v === 'true' || v === 1 || v === '1' ? 'true' : 'false';
}
function escFormula(v) {
  return String(v || '').replace(/\\/g, '\\\\').replace(/'/g, "\\'");
}

async function atFind(formula) {
  const res = await this.helpers.httpRequest({
    method: 'GET',
    url: `https://api.airtable.com/v0/${BASE}/${TABLE}`,
    qs: { filterByFormula: formula, maxRecords: 5 },
    headers: { Authorization: 'Bearer ' + TOKEN },
    json: true,
    timeout: 20000,
  });
  return res?.records || [];
}

async function atWrite(fields, recordId) {
  const body = recordId
    ? { records: [{ id: recordId, fields }], typecast: true }
    : { records: [{ fields }], typecast: true };
  const res = await this.helpers.httpRequest({
    method: recordId ? 'PATCH' : 'POST',
    url: `https://api.airtable.com/v0/${BASE}/${TABLE}`,
    headers: {
      Authorization: 'Bearer ' + TOKEN,
      'Content-Type': 'application/json',
    },
    body,
    json: true,
    timeout: 30000,
  });
  return res?.records?.[0] || null;
}

async function atDelete(recordId) {
  try {
    await this.helpers.httpRequest({
      method: 'DELETE',
      url: `https://api.airtable.com/v0/${BASE}/${TABLE}/${recordId}`,
