function isIgUsername(u) {
  const t = String(u || '').replace(/^@/, '').trim();
  return !!(t && !/^\d{5,}$/.test(t));
}

const store = $getWorkflowStaticData('global');
if (!store.igUsernames) store.igUsernames = {};
if (!store.clients) store.clients = {};

const rawIg = s(j.igUserId || j.at_ig_user_id || j.ig_user_id || '').trim();
const channelRaw = String(j.channel || '').toLowerCase();
const hasExplicitIg = /^\d{5,}$/.test(rawIg);
let igsid = hasExplicitIg ? rawIg : '';

// Prefer human Instagram username (ex: ahmad_nouri) — already resolved by Apply IG Username
let username = '';
for (const c of [j.instagramUsername, j.at_sender_id, j.senderId]) {
  const t = s(c).replace(/^@/, '').trim();
  if (isIgUsername(t)) { username = t; break; }
}
// Only treat numeric sender as IGSID when channel is already Instagram
const numericSender = s(j.senderId || j.at_sender_id).trim();
if (!igsid && channelRaw === 'instagram' && /^\d{8,}$/.test(numericSender)) igsid = numericSender;

if (!username && igsid) {
  username = s(store.igUsernames[igsid] || (store.clients[igsid] && store.clients[igsid].instagramUsername)).replace(/^@/, '').trim();
  if (!isIgUsername(username)) username = '';
}

// Instagram if channel says so OR explicit igUserId was provided
const isIg = channelRaw === 'instagram' || hasExplicitIg;
if (isIg && channelRaw !== 'whatsapp') {
  j.channel = 'instagram';
}

if (isIg) {
  const resolved = await resolveInstagramUsername(igsid || '', {
    ...j,
    instagramUsername: username || j.instagramUsername,
    senderId: username || j.senderId,
  });
  if (resolved.igUserId && /^\d{5,}$/.test(String(resolved.igUserId))) {
    igsid = String(resolved.igUserId);
    j.igUserId = igsid;
  }
  if (resolved.username) {
    username = resolved.username;
    j.instagramUsername = username;
    j.igUsernameResolved = true;
    if (igsid) store.igUsernames[igsid] = username;
  }
}

// sender_id = username (IG) or phone (WA). sender_id_num = IGSID or WA digits.
if (!username && isIg) {
  username = isIgUsername(j.instagramUsername) ? String(j.instagramUsername).replace(/^@/, '').trim() : '';
}
const finalIgsid = igsid || '';
let sender = username;
if (!sender && isIg && finalIgsid) {
  // Last-resort fallback: keep the conversation visible in Leads even if Meta username lookup is temporarily blocked.
  sender = 'ig_' + finalIgsid;
  j.instagramUsername = sender;
  j.igUsernameResolved = false;
  j.igProfileError = j.igProfileError || 'username_unresolved_fallback';
}
if (!sender && !isIg) {
  sender = s(j.at_sender_id || j.senderId || '').trim();
}
if (!isIg && !sender) {
  return [{ json: { ...j, airtableOk: false, airtableError: 'missing_sender_id' } }];
}
const digits = String(sender || '').replace(/\D/g, '');
const senderNum = (!isIg && /^\d{8,15}$/.test(digits)) ? Number(digits) : null;

const fields = {
  sender_id: sender || finalIgsid || 'unknown',
  prenom: s(j.prenom),
  channel: isIg ? 'instagram' : s(j.channel),
  langue: s(j.at_langue || (String(j.langue || '').toLowerCase() === 'darija' ? 'FR' : (j.langue || 'FR'))),
  intention: s(j.intention || 'autre'),
  prestation: s(j.prestation || 'inconnu'),
  pack: s(j.pack || j.packName || j.lastPackName || '').toLowerCase(),
  dernier_message: s(j.messageText, 5000),
  reponse_bot: s(j.finalResponse, 5000),
