};

// Only write valid pack choices (Airtable singleSelect)
if (!/^(basic|prestige|vip|diamond|mini)$/.test(String(fields.pack || ''))) delete fields.pack;
const mis = j.at_mis_a_jour || j.crmUpdatedAt || new Date().toISOString();
const lastMsg = j.at_last_message_at || j.last_message_at || new Date().toISOString();
if (mis) fields.mis_a_jour = mis;
if (lastMsg) fields.last_message_at = lastMsg;

// Drop empty optional strings so Airtable does not wipe with ""
for (const k of Object.keys(fields)) {
  if (fields[k] === '' || fields[k] === undefined || fields[k] === null) delete fields[k];
}
if (!isIg && senderNum != null && !Number.isNaN(senderNum)) fields.sender_id_num = senderNum;
if (isIg && finalIgsid && /^\d{5,}$/.test(String(finalIgsid))) fields.sender_id_num = Number(finalIgsid);

try {
  // Find existing row by ig_user_id OR sender_id(=igsid or username) to avoid duplicates
  const found = [];
  const seen = new Set();
  const formulas = [];
  if (finalIgsid) {
    formulas.push(`OR({sender_id}='${escFormula(finalIgsid)}',{sender_id_num}=${Number(finalIgsid)})`);
  }
  if (username) {
    formulas.push(`{sender_id}='${escFormula(username)}'`);
  }
  if (!formulas.length && sender) {
    formulas.push(`{sender_id}='${escFormula(sender)}'`);
  }
  for (const fml of formulas) {
    const rows = await atFind.call(this, fml);
    for (const r of rows) {
      if (seen.has(r.id)) continue;
      seen.add(r.id);
      found.push(r);
    }
  }
  found.sort((a, b) => {
    const ag = (a.fields && a.fields.sender_id_num) ? 1 : 0;
    const bg = (b.fields && b.fields.sender_id_num) ? 1 : 0;
    if (bg !== ag) return bg - ag;
    const au = isIgUsername(a.fields && a.fields.sender_id) ? 1 : 0;
    const bu = isIgUsername(b.fields && b.fields.sender_id) ? 1 : 0;
    return bu - au;
  });

  const primary = found[0] || null;
  // Never overwrite a stored username with a numeric IGSID (Instagram only)
  if (isIg && primary) {
    const existingSid = s(primary.fields && primary.fields.sender_id).replace(/^@/, '').trim();
    if (!isIgUsername(sender) && isIgUsername(existingSid)) {
      sender = existingSid;
      username = existingSid;
      j.instagramUsername = existingSid;
    }
  }
  if (isIg) {
    if (!isIgUsername(sender)) sender = username || '';
    if (isIgUsername(sender)) {
      fields.sender_id = sender;
    } else if (!primary) {
      // New IG lead without username yet: skip numeric fake id
      return [{ json: {
        ...j,
        channel: fields.channel || j.channel,
        igUserId: finalIgsid || j.igUserId || '',
        airtableOk: false,
        airtableError: 'ig_username_unresolved',
        airtableMergeOn: 'skip',
      } }];
    } else {
      delete fields.sender_id;
    }
  } else {
    // WhatsApp / other: phone (or text id) is a valid sender_id
    if (!sender) {
      return [{ json: { ...j, airtableOk: false, airtableError: 'missing_sender_id' } }];
    }
    fields.sender_id = sender;
  }

  if (isIg && !fields.sender_id && !primary) {
    return [{ json: { ...j, airtableOk: false, airtableError: 'missing_sender_id' } }];
  }

  const saved = await atWrite.call(this, fields, primary ? primary.id : '');
  // Clean orphan duplicates for same Instagram person
  if (finalIgsid && found.length > 1) {
    for (const r of found.slice(1)) {
      const sid = String((r.fields && r.fields.sender_id) || '');
      const num = String((r.fields && r.fields.sender_id_num) || '');
      if (sid === finalIgsid || num === finalIgsid || (username && sid === username) || (sender && sid === sender)) {
        await atDelete.call(this, r.id);
      }
    }
  }

  return [{ json: {
    ...j,
    channel: fields.channel || j.channel,
    igUserId: finalIgsid || j.igUserId || '',
    instagramUsername: username || j.instagramUsername || (isIgUsername(sender) ? sender : ''),
    senderId: isIgUsername(sender) ? sender : (j.senderId || sender),
    airtableOk: true,
    airtableRecordId: saved?.id || (primary && primary.id) || '',
    airtableError: '',
    airtableMergeOn: primary ? 'find_patch' : 'create',
  } }];
} catch (e) {
  return [{ json: {
    ...j,
    igUserId: finalIgsid || j.igUserId || '',
    airtableOk: false,
    airtableError: String(e.message || e).slice(0, 800),
  } }];
}

