function s(v, max) {
  const t = v == null ? "" : String(v);
  return max ? t.slice(0, max) : t;
}

function escFormula(v) {
  return String(v || "").replace(/\\/g, "\\\\").replace(/'/g, "\\'");
}

function sanitizeLangue(raw) {
  const x = String(raw || "FR").trim();
  if (/^en/i.test(x)) return "EN";
  if (/^ar/i.test(x)) return "AR";
  return "FR";
}

/** Never store intents / sentences as a person name */
function cleanPersonName(raw) {
  let t = String(raw || "").trim().replace(/\s+/g, " ");
  if (!t) return "";
  if (/^(cliente\s+YOUR_BUSINESS_NAME|ch[eè]re\s+cliente)$/i.test(t)) return "";
  if (t.length > 40) return "";
  if (t.split(" ").length > 3) return "";
  // Junk typos that must never become Enfants rows
  if (/^(.)\1+$/i.test(t)) return "";
  if (t.length <= 3 && !/[aeiouyàâäéèêëïîôùûüœ]/i.test(t) && !/[\u0600-\u06FF]/.test(t)) return "";
  if (/[@/\\d]/.test(t) && /@/.test(t)) return "";
  if (/\b(annul|reserv|rendez[- ]?vous|voudrais|voudrait|bonjour|bonsoir|salut|couple|famille|newborn|grossesse|cake|smash|vip|diamond|prestige|basic|reporter|d[eé]plac|replanif|email|mail|cr[eé]neau|s[eé]ance|shooting|pack|oui|non|merci|cette|cet|ce|ces|mon|ma|mes|offre|fille|fils|enfant|votre|vos|vous|notre|pour|avec|dans|de|du|des|la|le|les|mere|m[eè]re|pere|p[eè]re|maman|papa)\b/i.test(t)) {
    return "";
  }
  if (!/^[A-Za-zÀ-ÿ\u0600-\u06FF][A-Za-zÀ-ÿ\u0600-\u06FF'’\- ]{1,39}$/.test(t)) return "";
  return t;
}

function mapPrestation(raw) {
  const p = String(raw || "").toLowerCase().trim();
  const allowed = [
    "grossesse", "newborn", "cake_smash", "birthday",
    "famille", "couple", "solo", "sitter", "autre",
  ];
  if (allowed.includes(p)) return p;
  if (/first.?year|1ere|premi/.test(p)) return "birthday";
  if (/smash/.test(p)) return "cake_smash";
  if (/new.?born|nouveau/.test(p)) return "newborn";
  if (/gross/.test(p)) return "grossesse";
  if (/famil/.test(p)) return "famille";
  if (/coupl/.test(p)) return "couple";
  if (/solo|portrait/.test(p)) return "solo";
  if (/sitter/.test(p)) return "sitter";
  if (/birth|anniv/.test(p)) return "birthday";
  // Airtable Séances.prestation has no "autre" option — omit via empty
  return "";
}

function mapPack(raw) {
  const p = String(raw || "").toLowerCase().trim();
  if (!p) return "";
  if (["basic", "prestige", "vip", "diamond", "mini"].includes(p)) return p;
  if (/diamond/.test(p)) return "diamond";
  if (/\bvip\b/.test(p)) return "vip";
  if (/prestige/.test(p)) return "prestige";
  if (/basic|basique/.test(p)) return "basic";
  if (/\bmini\b/.test(p)) return "mini";
  return "";
}

function collectEnfantNames(payload) {
  const out = [];
  const seen = new Set();
  const parentName = cleanPersonName(payload.prenom || payload.clientName || "").toLowerCase();
  function push(n) {
    const c = cleanPersonName(n);
    if (!c) return;
    const key = c.toLowerCase();
    // Never store parent as enfant
    if (parentName && key === parentName) return;
    if (seen.has(key)) return;
    seen.add(key);
    out.push(c);
  }
  if (Array.isArray(payload.enfants)) {
    for (const e of payload.enfants) {
      if (typeof e === "string") push(e);
      else if (e && e.prenom) push(e.prenom);
    }
  }
  if (Array.isArray(payload.enfant_prenoms)) {
    for (const e of payload.enfant_prenoms) push(e);
  }
  const single = payload.enfant_prenom || payload.childName || payload.prenom_enfant;
  if (single) {
    String(single)
      .split(/\s*(?:,|;|\/|\bet\b|\band\b|\+|&)\s*/i)
      .forEach(push);
  }
  return out;
}

function collectEnfantsDetailed(payload) {
  const parentName = cleanPersonName(payload.prenom || payload.clientName || "").toLowerCase();
  const names = collectEnfantNames(payload);
  const detailed = [];
  if (Array.isArray(payload.enfants) && payload.enfants.length && typeof payload.enfants[0] === "object") {
    for (const e of payload.enfants) {
      const prenom = cleanPersonName(e && e.prenom);
      if (!prenom) continue;
      if (parentName && prenom.toLowerCase() === parentName) continue;
      const dob = s(e.date_naissance || e.dob || "").trim();
      detailed.push({
        prenom,
        date_naissance: /^\d{4}-\d{2}-\d{2}/.test(dob) ? dob.slice(0, 10) : "",
        remarques: s(e.remarques || e.notes || "", 1000),
      });
    }
  }
  if (detailed.length) return detailed;
  const dobsRaw = Array.isArray(payload.enfant_dobs) ? payload.enfant_dobs : [];
  const singleDob = s(payload.date_naissance || payload.childDob || payload.enfant_date_naissance).trim();
  const iso = /^\d{4}-\d{2}-\d{2}/.test(singleDob) ? singleDob.slice(0, 10) : "";
  const sharedRem = s(payload.enfant_remarques || "", 1000);
  return names.map((n, i) => {
    const d = s(dobsRaw[i] || "").trim();
    const dob = /^\d{4}-\d{2}-\d{2}/.test(d) ? d.slice(0, 10) : (names.length === 1 ? iso : (i === 0 ? iso : ""));
    return { prenom: n, date_naissance: dob, remarques: sharedRem };
  });
}

function fmtSeanceLine(fields) {
  const f = fields || {};
  const when = String(f.scheduled_at || "").replace("T", " ").slice(0, 16);
  const prest = f.prestation || "séance";
  const pack = f.pack ? (" " + String(f.pack).toUpperCase()) : "";
  const link = f.lien_reservation || "";
  return { dateLine: (when || "?") + " — " + prest + pack, linkLine: link || "" };
}

async function airtable(method, table, qs, body) {
  const opts = {
    method,
    url: `https://api.airtable.com/v0/${BASE}/${encodeURIComponent(table)}`,
    headers: {
      Authorization: "Bearer " + TOKEN,
      "Content-Type": "application/json",
    },
    json: true,
    timeout: 30000,
  };
  if (qs) opts.qs = qs;
  if (body) opts.body = body;
  return await this.helpers.httpRequest(opts);
}

async function upsertByMerge(table, mergeField, fields) {
  const clean = { ...fields };
  for (const k of Object.keys(clean)) {
    if (clean[k] === "" || clean[k] === undefined || clean[k] === null) delete clean[k];
  }
  if (!clean[mergeField]) {
    throw new Error("missing_merge_" + mergeField);
  }
  const res = await airtable.call(this, "PATCH", table, null, {
    performUpsert: { fieldsToMergeOn: [mergeField] },
    records: [{ fields: clean }],
    typecast: true,
  });
  return (res && res.records && res.records[0]) || null;
}

/** Find existing Client by ig_user_id and/or sender_id, then PATCH — avoids IG duplicates. */
async function findThenUpsertClient(fields, igsid, senderId) {
  const clean = { ...fields };
  for (const k of Object.keys(clean)) {
    if (clean[k] === "" || clean[k] === undefined || clean[k] === null) delete clean[k];
  }
  const found = [];
  const seen = new Set();
  const formulas = [];
  if (igsid) {
    formulas.push(`OR({ig_user_id}='${escFormula(igsid)}',{sender_id}='${escFormula(igsid)}')`);
  }
  if (senderId && senderId !== igsid) {
    formulas.push(`{sender_id}='${escFormula(senderId)}'`);
  }
  for (const fml of formulas) {
    const res = await airtable.call(this, "GET", T_CLIENTS, { filterByFormula: fml, maxRecords: 5 });
    for (const r of (res && res.records) || []) {
      if (seen.has(r.id)) continue;
      seen.add(r.id);
      found.push(r);
    }
  }
  found.sort((a, b) => {
    const ag = (a.fields && a.fields.ig_user_id) ? 1 : 0;
    const bg = (b.fields && b.fields.ig_user_id) ? 1 : 0;
    return bg - ag;
  });
  const primary = found[0] || null;
  if (primary) {
    // Preserve username sender_id / instagram handle — never replace with numeric IGSID
    const exSid = s(primary.fields && primary.fields.sender_id).replace(/^@/, "").trim();
    const exIg = s(primary.fields && primary.fields.instagram).replace(/^@/, "").trim();
    const isUser = (u) => !!(u && !/^\d{5,}$/.test(u));
    if (!isUser(clean.sender_id) && isUser(exSid)) clean.sender_id = exSid;
    if (!isUser(clean.instagram) && isUser(exIg || exSid)) clean.instagram = exIg || exSid;
    if (igsid) clean.ig_user_id = igsid;
  }
  if (primary) {
    const res = await airtable.call(this, "PATCH", T_CLIENTS, null, {
      records: [{ id: primary.id, fields: clean }],
      typecast: true,
    });
    // Drop orphan duplicates for same IG person
    if (igsid && found.length > 1) {
      for (const r of found.slice(1)) {
        const sid = String((r.fields && r.fields.sender_id) || "");
        const ig = String((r.fields && r.fields.ig_user_id) || "");
        if (sid === igsid || ig === igsid || (senderId && sid === senderId)) {
          try {
            await airtable.call(this, "DELETE", T_CLIENTS + "/" + r.id);
          } catch (e) {
            try {
              await this.helpers.httpRequest({
                method: "DELETE",
                url: `https://api.airtable.com/v0/${BASE}/${encodeURIComponent(T_CLIENTS)}/${r.id}`,
                headers: { Authorization: "Bearer " + TOKEN },
                json: true,
                timeout: 15000,
              });
            } catch (e2) {}
          }
        }
      }
    }
    return (res && res.records && res.records[0]) || primary;
  }
  const res = await airtable.call(this, "POST", T_CLIENTS, null, {
    records: [{ fields: clean }],
    typecast: true,
  });
  return (res && res.records && res.records[0]) || null;
}

const sender = s(j.at_sender_id || j.instagramUsername || j.senderId || "").trim();
const out = {
  ...j,
  crmSyncOk: false,
  crmClientId: "",
  crmSeanceId: "",
  crmEnfantId: "",
  crmEnfantIds: [],
  crmSyncError: "",
};

if (!sender) {
  out.crmSyncError = "missing_sender_id";
  return [{ json: out }];
}

const nowIso = new Date().toISOString();
const channelRaw = String(j.channel || "").toLowerCase();
const explicitIg = s(j.igUserId || j.at_ig_user_id || j.ig_user_id).trim();
const hasExplicitIg = /^\d{5,}$/.test(explicitIg);
// Stable Instagram scoped id (numeric). Username alone is not enough to identify the person.
const igsid = (() => {
  if (hasExplicitIg) return explicitIg;
  if (channelRaw !== "instagram") return "";
  for (const c of [j.senderId, j.at_sender_id, sender]) {
    const t = s(c).trim();
    if (/^\d{5,}$/.test(t)) return t;
  }
  return "";
})();
const isIg = channelRaw === "instagram" || hasExplicitIg;
const channel = isIg ? "instagram" : "whatsapp";
const safePrenom = cleanPersonName(j.prenom || j.clientName || "");
const igUsername = s(
  j.instagramUsername || (isIg && !/^\d{5,}$/.test(sender) ? sender : "")
).replace(/^@/, "").trim();

try {
  // --- 1) Clients (foyer) ---
  const clientFields = {
    // Instagram: username only in sender_id (never numeric IGSID)
    sender_id: isIg
      ? (igUsername || (!/^\d{5,}$/.test(sender) ? sender : ""))
      : sender,
    telephone: isIg ? "" : sender,
    email: s(j.at_client_email || j.client_email || j.email, 200),
    channel,
    ville: s(j.ville || "YOUR_BUSINESS_CITY", 80),
    langue: sanitizeLangue(j.at_langue || j.langue),
    status: j.status === "STOP" ? "STOP" : "ACTIVE",
    mis_a_jour: s(j.at_mis_a_jour || j.crmUpdatedAt || nowIso),
  };
  if (isIg) {
    if (igsid) clientFields.ig_user_id = igsid;
    if (igUsername) {
      clientFields.instagram = igUsername;
      clientFields.sender_id = igUsername;
    }
  } else if (j.instagramUsername) {
    clientFields.instagram = s(j.instagramUsername, 120);
  }
  // nom_foyer = prénom + numéro (WA) ou prénom + @username (IG)
  const idPart = isIg
    ? (igUsername || (!/^\d{5,}$/.test(String(clientFields.sender_id || sender)) ? String(clientFields.sender_id || sender) : ""))
    : (s(j.telephone || clientFields.telephone || sender).replace(/\D/g, "") || String(sender || ""));
  if (safePrenom) {
    clientFields.prenom = safePrenom;
    clientFields.nom_foyer = idPart
      ? (safePrenom + " " + (isIg ? ("@" + idPart.replace(/^@/, "")) : idPart)).slice(0, 80)
      : safePrenom;
  } else {
    clientFields.nom_foyer = isIg
      ? ("@" + (igUsername || (!/^\d{5,}$/.test(String(sender)) ? sender : "instagram")).replace(/^@/, "")).slice(0, 40)
      : ("Client " + String(idPart || sender).slice(-10));
  }

  // Notes client (thème / remarques / préférences mentionnés)
  const incomingNotes = s(j.notes || j.bookingNotes || j.client_notes, 2000);
  const theme = s(j.theme || j.seance_theme, 120);
  if (incomingNotes || theme) {
    const noteBits = [];
    if (theme) noteBits.push("Thème: " + theme);
    if (incomingNotes) noteBits.push(incomingNotes);
    clientFields.notes = noteBits.join(" · ").slice(0, 2000);
  }

  // Instagram: find by ig_user_id OR sender_id(=igsid) then PATCH — no duplicate rows.
  // WhatsApp: merge on sender_id (phone).
  let clientRec;
  if (isIg) {
    if (igsid) clientFields.ig_user_id = igsid;
    clientRec = await findThenUpsertClient.call(
      this,
      clientFields,
      igsid,
      clientFields.sender_id || sender
    );
  } else {
    clientRec = await upsertByMerge.call(this, T_CLIENTS, "sender_id", clientFields);
  }
  const clientId = (clientRec && clientRec.id) || "";
  out.crmClientId = clientId;

  // --- 2) Séances (si RDV) ---
  const cancelled = j.annule === true || j.annule === "true" || String(j.annule) === "true";
  const cancelUid = s(
    j.cancelled_appointment_id
    || (cancelled ? (j.bookingUid || j.appointment_id || (j.deleteResult && j.deleteResult.bookingUid)) : "")
  ).trim();
  const appointmentId = s(j.appointment_id || cancelUid).trim();
  const previousAppt = s(
    j.previous_appointment_id
    || (j.updateResult && j.updateResult.rescheduledFromUid)
    || ""
  ).trim();
  // Live tool results only — sticky bookingCreated/reporte must NOT re-upsert every later turn
  // (otherwise a 2nd-RDV chat overwrites the 1st Séances row with the new prestation).
  const updatedNow = !!(
    (j.updateResult && j.updateResult.ok)
    || j.bookingUpdated === true
    || j.bookingUpdated === "true"
  );
  const createdNow = !!(j.bookingResult && j.bookingResult.ok);
  const bookedNow = !!(createdNow || updatedNow);
  // Sticky flags: bootstrap missing Séances row only (never overwrite existing)
  const stickyCreated = !!(
    j.bookingCreated === true
    || j.bookingCreated === "true"
  );
  const hasBookingLink = !!(
    s(j.lien_reservation || j.calBookingLink || j.booking_link).match(/cal\.com\/booking\//i)
  );
  // IMPORTANT: do NOT re-sync on every turn just because scheduled_at exists.
  const richPatch = !!(theme || incomingNotes);
  // Bootstrap: if we have a Cal uid (+ usually a link) ensure a Séances row exists
  const shouldSyncSeance = !!appointmentId && (
    bookedNow || cancelled || !!cancelUid || richPatch || hasBookingLink
  );

  async function findSeanceByAppt(appt) {
    const id = s(appt).trim();
    if (!id) return null;
    try {
      const found = await airtable.call(this, "GET", T_SEANCES, {
        filterByFormula: `{appointment_id} = '${escFormula(id)}'`,
        maxRecords: 1,
      });
      return ((found && found.records) || [])[0] || null;
    } catch (eFind) {
      return null;
    }
  }

  async function patchSeanceRecord(recId, fields) {
    const clean = { ...fields };
    for (const k of Object.keys(clean)) {
      if (clean[k] === "" || clean[k] === undefined || clean[k] === null) delete clean[k];
    }
    const upd = await airtable.call(this, "PATCH", T_SEANCES, null, {
      records: [{ id: recId, fields: clean }],
      typecast: true,
    });
    return (upd && upd.records && upd.records[0]) || null;
  }

  async function refreshClientSeanceStats(cid) {
    if (!cid) return;
    try {
      const listed = await airtable.call(this, "GET", T_SEANCES, {
        filterByFormula: "{statut} = 'booked'",
        maxRecords: 100,
      });
      const recs = ((listed && listed.records) || []).filter((r) => {
        const links = (r.fields && r.fields.client) || [];
        return Array.isArray(links) && links.includes(cid);
      });
      // sort by scheduled_at
      recs.sort((a, b) => String((a.fields || {}).scheduled_at || "").localeCompare(String((b.fields || {}).scheduled_at || "")));
      const years = [];
      const dateLines = [];
      const linkLines = [];
      for (const r of recs) {
        const f = r.fields || {};
        const y = Number(f.annee || 0);
        if (y) years.push(y);
        const line = fmtSeanceLine(f);
        if (line.dateLine) dateLines.push(line.dateLine);
        if (line.linkLine) linkLines.push(line.linkLine);
      }
      const patch = {
        nombre_seances: recs.length,
        dates_reservations: dateLines.join("\n"),
        liens_reservations: linkLines.join("\n"),
        mis_a_jour: nowIso,
      };
      if (years.length) {
        patch.premiere_annee = Math.min(...years);
        patch.derniere_annee = Math.max(...years);
      } else {
        patch.premiere_annee = null;
        patch.derniere_annee = null;
      }
      await airtable.call(this, "PATCH", T_CLIENTS, null, {
        records: [{ id: cid, fields: patch }],
        typecast: true,
      });
    } catch (eCount) {
      // non-bloquant
    }
  }

  // --- 3) Enfants — sync exact list from bot memory (create/update + delete orphans)
  const enfantsDetailed = collectEnfantsDetailed(j);
  const enfantIds = [];
  const deletedEnfantIds = [];
  const skipEnfantCreate = !!(updatedNow || cancelled) && !createdNow;
  const desiredNames = new Set(
    enfantsDetailed.map((c) => String(c.prenom || "").toLowerCase()).filter(Boolean)
  );
  // Always reconcile when we have a client: memory is source of truth for child list.
  // (Empty desiredNames after a correction must delete leftover Airtable rows like "Ww".)
  const shouldReconcileEnfants = !!clientId && (
    Array.isArray(j.enfants)
    || Array.isArray(j.enfant_prenoms)
    || j.enfantsCorrected === true
    || enfantsDetailed.length > 0
  );

  if (clientId && shouldReconcileEnfants) {
    let existingForClient = [];
    try {
      // List + filter in JS (Airtable linked-record formulas are unreliable across bases)
      const foundAll = await airtable.call(this, "GET", T_ENFANTS, {
        maxRecords: 100,
      });
      existingForClient = ((foundAll && foundAll.records) || []).filter((r) => {
        const links = (r.fields && r.fields.client) || [];
        return Array.isArray(links) && links.includes(clientId);
      });
    } catch (eList) {
      existingForClient = [];
    }

    // Delete orphans not in desired list
    for (const rec of existingForClient) {
      const name = String((rec.fields && rec.fields.prenom) || "").trim();
      if (!name) continue;
      if (!desiredNames.has(name.toLowerCase())) {
        try {
          await this.helpers.httpRequest({
            method: "DELETE",
            url: `https://api.airtable.com/v0/${BASE}/${encodeURIComponent(T_ENFANTS)}/${rec.id}`,
            headers: { Authorization: "Bearer " + TOKEN },
            json: true,
            timeout: 15000,
          });
          deletedEnfantIds.push(rec.id);
        } catch (eDel) {
          out.crmEnfantDeleteError = String(eDel.message || eDel).slice(0, 200);
        }
      }
    }

    for (const child of enfantsDetailed) {
      const childName = child.prenom;
      let enfant = existingForClient.find((r) => {
        const n = String((r.fields && r.fields.prenom) || "").toLowerCase();
        return n === String(childName).toLowerCase() && !deletedEnfantIds.includes(r.id);
      }) || null;
      if (!enfant) {
        try {
          const found = await airtable.call(this, "GET", T_ENFANTS, {
            filterByFormula: `{prenom} = '${escFormula(childName)}'`,
            maxRecords: 20,
          });
          const list = (found && found.records) || [];
          enfant = list.find((r) => {
            const links = (r.fields && r.fields.client) || [];
            return Array.isArray(links) && links.includes(clientId);
          }) || null;
        } catch (eFind) {
          enfant = null;
        }
      }
      const enfantFields = {
        prenom: childName,
        client: [clientId],
      };
      const childRem = s(child.remarques || j.enfant_remarques, 1000);
      if (childRem) enfantFields.remarques = childRem;
      if (child.date_naissance) {
        enfantFields.date_naissance = child.date_naissance;
      }
      if (enfant && enfant.id && !deletedEnfantIds.includes(enfant.id)) {
        const upd = await airtable.call(this, "PATCH", T_ENFANTS, null, {
          records: [{ id: enfant.id, fields: enfantFields }],
          typecast: true,
        });
        enfantIds.push((upd && upd.records && upd.records[0] && upd.records[0].id) || enfant.id);
      } else if (!skipEnfantCreate) {
        const created = await airtable.call(this, "POST", T_ENFANTS, null, {
          records: [{ fields: enfantFields }],
          typecast: true,
        });
        const id = (created && created.records && created.records[0] && created.records[0].id) || "";
        if (id) enfantIds.push(id);
      } else if (enfant && enfant.id) {
        enfantIds.push(enfant.id);
      }
    }
  }
  out.crmEnfantIds = enfantIds;
  out.crmEnfantId = enfantIds[0] || "";
  out.crmEnfantsDeleted = deletedEnfantIds;

  if (shouldSyncSeance) {
    const prestation = mapPrestation(j.prestation);
    const pack = mapPack(
      j.packName || j.pack || j.selectedPack || j.calPack || j.lastPackName
      || (j.myBookings && j.myBookings[0] && j.myBookings[0].packName)
    );
    const scheduled = s(j.at_scheduled_at || j.scheduled_at);
    let year = 0;
    if (scheduled) {
      const d = new Date(scheduled);
      if (!Number.isNaN(d.getTime())) year = d.getFullYear();
    }
    if (!year) year = new Date().getFullYear();

    const titreParts = [
      prestation || "séance",
      pack ? pack.toUpperCase() : "",
      scheduled ? scheduled.slice(0, 10) : "",
    ].filter(Boolean);

    const isCancelTarget = !!(cancelled || (cancelUid && cancelUid === appointmentId));
    let statut = isCancelTarget ? "cancelled" : "booked";

    const seanceFields = {
      appointment_id: appointmentId,
      titre: s(titreParts.join(" — "), 200),
      annee: year,
      ville: s(j.ville || "YOUR_BUSINESS_CITY", 80),
      scheduled_at: scheduled || undefined,
      lien_reservation: s(j.lien_reservation || j.calBookingLink || j.booking_link, 500),
      statut,
      source: "bot",
      mis_a_jour: nowIso,
      remarque: s(j.bookingNotes || j.notes || incomingNotes, 2000),
      theme: theme || undefined,
    };
    if (prestation) seanceFields.prestation = prestation;
    if (pack) seanceFields.pack = pack;
    if (clientId) seanceFields.client = [clientId];
    if (enfantIds.length) seanceFields.enfant = enfantIds;

    // REPORT: Cal.com change souvent l'uid → modifier LA MÊME ligne Séances (pas créer + cancel)
    const isReschedule = !!(
      updatedNow
      && previousAppt
      && appointmentId
      && previousAppt !== appointmentId
      && !isCancelTarget
    );

    if (isReschedule) {
      const oldRec = await findSeanceByAppt.call(this, previousAppt);
      if (oldRec && oldRec.id) {
        const seanceRec = await patchSeanceRecord.call(this, oldRec.id, seanceFields);
        out.crmSeanceId = (seanceRec && seanceRec.id) || oldRec.id;
        out.crmSeanceUpdatedInPlace = true;
        out.crmSeancePreviousAppt = previousAppt;
      } else {
        // Pas de ligne ancienne trouvée → upsert sur le nouvel uid (1 seule ligne)
        const seanceRec = await upsertByMerge.call(this, T_SEANCES, "appointment_id", seanceFields);
        out.crmSeanceId = (seanceRec && seanceRec.id) || "";
      }
    } else if (richPatch && !bookedNow && !isCancelTarget) {
      const light = {
        appointment_id: appointmentId,
        mis_a_jour: nowIso,
        source: "bot",
      };
      if (theme) light.theme = theme;
      if (incomingNotes || j.bookingNotes || j.notes) {
        light.remarque = s(j.bookingNotes || j.notes || incomingNotes, 2000);
      }
      if (clientId) light.client = [clientId];
      if (enfantIds.length) light.enfant = enfantIds;
      const seanceRec = await upsertByMerge.call(this, T_SEANCES, "appointment_id", light);
      out.crmSeanceId = (seanceRec && seanceRec.id) || "";
    } else if (bookedNow || isCancelTarget) {
      // Create OR cancel: upsert même appointment_id (1 ligne)
      const seanceRec = await upsertByMerge.call(this, T_SEANCES, "appointment_id", seanceFields);
      out.crmSeanceId = (seanceRec && seanceRec.id) || "";
