out = out.replace(/<function\s*=[\s\S]*?(<\/function>|$)/gi, '')
  .replace(/<tool_call[\s\S]*?(<\/tool_call>|$)/gi, '')
  .replace(/```(?:json)?[\s\S]*?```/gi, '')
  .trim();
if (!out) out = 'Thanks for your message. A member of our team will get back to you shortly.';

const message = String(mem.messageText || '').toLowerCase();
const escalationPattern = /complaint|manager|human|agent|refund|angry|bad service|plainte|réclamation|responsable|humain|conseiller|mécontent|mauvais service/i;
const escalated = escalationPattern.test(message) || /we.*(?:team|manager)|transferr|recontact/i.test(out);
const store = $getWorkflowStaticData('global');
if (!store.clients) store.clients = {};
const key = mem.igUserId || mem.senderId || mem.sessionId;
const previous = store.clients[key] || {};
if (key) {
  store.clients[key] = {
    ...previous,
    prenom: mem.prenom || previous.prenom || '',
    langue: mem.langue || previous.langue || 'EN',
    prestation: mem.prestation || previous.prestation || '',
    packName: mem.packName || mem.pack || previous.packName || '',
    clientEmail: mem.clientEmail || previous.clientEmail || '',
    updatedAt: new Date().toISOString(),
  };
}
return [{ json: {
  ...mem,
  finalResponse: out,
  output: out,
  escalated,
  escalade_requise: escalated,
  intention: escalated ? 'escalation' : (mem.intention || 'general_question'),
  status: escalated ? 'ESCALATED' : 'ACTIVE',
  channel: mem.channel || 'test',
  sessionId: mem.sessionId || mem.igUserId || mem.senderId || '',
} }];

function parseArgs(q) {
  if (q && typeof q === 'object' && !Array.isArray(q)) return q;
  const s = String(q || '').trim();
  if (!s) return {};
  try { return JSON.parse(s); } catch (e1) {}
  try {
    const m = s.match(/\{[\s\S]*\}/);
    if (m) return JSON.parse(m[0]);
  } catch (e2) {}
  const out = {};
  for (const part of s.split(/[,&\n]+/)) {
    const kv = part.match(/^\s*([A-Za-z0-9_]+)\s*[:=]\s*(.+?)\s*$/);
    if (kv) out[kv[1]] = kv[2].replace(/^["']|["']$/g, '');
  }
  return out;
}
function cap(n) {
  const t = String(n || '').trim();
  if (!t) return '';
  return t.charAt(0).toUpperCase() + t.slice(1);
}
function blocked(n) {
  return /^(oui|non|ok|vip|diamond|prestige|basic|mini|lundi|mardi|mercredi|jeudi|vendredi|samedi|dimanche|couple|famille|newborn|sitter|votre|vos|vous|de|du|des|la|le|les|mon|ma|mes|fils|fille|enfant|mere|m[eè]re|maman|papa|il|elle|comment|quoi|pourquoi|combien|quand|o[uù]|comment|svp|merci|bonjour|salut|hello|hey|aide|help|dis|donne|peux|veux|réserve|reserve|annule|reporte)$/i.test(String(n || '').trim());
}
function isJunkKidName(n) {
  const t = String(n || '').trim();
  if (!t || t.length < 2) return true;
  if (/^(.)\1+$/i.test(t)) return true; // ww, xx, aaa
  if (t.length <= 3 && !/[aeiouyàâäéèêëïîôùûüœ]/i.test(t) && !/[\u0600-\u06FF]/.test(t)) return true;
  return false;
}
function cleanName(n) {
  const t = String(n || '').replace(/[^A-Za-zÀ-ÿ\u0600-\u06FF'’\- ]/g, '').trim();
  if (!t || t.length > 40 || blocked(t) || isJunkKidName(t)) return '';
  if (t.split(/\s+/).length > 3) return '';
  return cap(t.split(/\s+/)[0]);
}
function mapPack(p) {
  const x = String(p || '').toLowerCase().trim();
  if (/diamond/.test(x)) return 'diamond';
  if (/\bvip\b|vip+/.test(x)) return 'vip';
  if (/prestige/.test(x)) return 'prestige';
  if (/basic|basique/.test(x)) return 'basic';
  if (/\bmini\b/.test(x)) return 'mini';
  return '';
}
function mapPrest(p) {
  const x = String(p || '').toLowerCase().trim();
  if (/sitter/.test(x)) return 'sitter';
  if (/newborn|nouveau/.test(x)) return 'newborn';
  if (/cake|smash/.test(x)) return 'cake_smash';
  if (/birthday|anniv/.test(x)) return 'birthday';
  if (/famil/.test(x)) return 'famille';
  if (/couple/.test(x)) return 'couple';
  if (/solo|portrait/.test(x)) return 'solo';
  if (/gross|materni|enceinte/.test(x)) return 'grossesse';
  if (/first.?year|premiere/.test(x)) return 'first_year';
  return '';
}

const args = parseArgs(query);
const store = $getWorkflowStaticData('global');
if (!store.clients) store.clients = {};

let key = String(args.sessionId || args.senderId || args.session || '').trim();
if (!key) {
  try {
    const prep = $('Prep Agent Input').first().json || {};
    key = String(prep.igUserId || prep.senderId || prep.sessionId || '').trim();
  } catch (e0) {}
}
if (!key) {
  return JSON.stringify({ ok: false, error: 'missing_sessionId', hint: 'Pass sessionId from [SESSION]' });
}

const c = store.clients[key] || {};
const parent = cleanName(args.prenom || args.parentPrenom || args.clientName || args.name || '');
const email = String(args.email || args.clientEmail || '').trim();
const pack = mapPack(args.pack || args.packName || '');
const prestation = mapPrest(args.prestation || args.session || '');
const theme = String(args.theme || args.decor || '').trim().slice(0, 80);
const notesIn = String(args.notes || args.bookingNotes || args.remarques || '').trim().slice(0, 1500);

function toIsoDobSave(raw) {
  const s = String(raw || '').trim();
  if (!s) return '';
  if (/^\d{4}-\d{2}-\d{2}/.test(s)) return s.slice(0, 10);
  const m = s.match(/^(\d{1,2})[\/.\-](\d{1,2})[\/.\-](\d{2,4})$/);
  if (!m) return '';
  let d = parseInt(m[1], 10), mo = parseInt(m[2], 10), y = parseInt(m[3], 10);
  if (y < 100) y += 2000;
  if (y < 1990 || y > 2035 || mo < 1 || mo > 12 || d < 1 || d > 31) return '';
  return y + '-' + String(mo).padStart(2, '0') + '-' + String(d).padStart(2, '0');
}
let kids = [];
let kidsDobByName = {};
const kidsKeyPresent = ('enfants' in args) || ('children' in args) || ('enfant_prenoms' in args)
  || ('enfant' in args) || ('childName' in args) || ('enfantPrenom' in args);
const rawKids = args.enfants || args.children || args.enfant_prenoms || args.enfant || args.childName || args.enfantPrenom || [];
if (Array.isArray(rawKids)) {
  for (const k of rawKids) {
    if (typeof k === 'object' && k) {
      const n = cleanName(k.prenom || k.name);
      if (n && (!parent || n.toLowerCase() !== parent.toLowerCase())) {
        kids.push(n);
        const d = toIsoDobSave(k.date_naissance || k.dob || '');
        if (d) kidsDobByName[n.toLowerCase()] = d;
      }
    } else {
      const n = cleanName(k);
      if (n && (!parent || n.toLowerCase() !== parent.toLowerCase())) kids.push(n);
    }
  }
} else if (rawKids) {
  for (const part of String(rawKids).split(/\s*(?:,|;|\/|\bet\b|\band\b|\+)\s*/i)) {
    const n = cleanName(part);
    if (n && (!parent || n.toLowerCase() !== parent.toLowerCase())) kids.push(n);
  }
}
// dedupe
kids = [...new Set(kids.map((x) => x.toLowerCase()))].map(cap);

// Explicit removals: remove_enfants / removeEnfant
const rawRemove = args.remove_enfants || args.removeEnfants || args.remove_enfant || [];
const removeNames = [];
const remList = Array.isArray(rawRemove) ? rawRemove : String(rawRemove || '').split(/[,;]/);
for (const r of remList) {
  const n = cleanName(typeof r === 'string' ? r : (r && r.prenom));
  // cleanName may reject junk — still allow removing junk already stored
  const raw = String(typeof r === 'string' ? r : (r && (r.prenom || r.name)) || '').replace(/[^A-Za-zÀ-ÿ\u0600-\u06FF'’\- ]/g, '').trim();
  const name = n || (raw ? cap(raw.split(/\s+/)[0]) : '');
  if (name) removeNames.push(name.toLowerCase());
}

if (parent) c.prenom = parent;
if (email && email.includes('@')) c.clientEmail = email;
if (pack) { c.packName = pack; c.pack = pack; c.lastPackName = pack; }
if (prestation) { c.prestation = prestation; c.lastPrestation = prestation; }
if (theme) c.theme = theme;
if (notesIn) {
  c.bookingNotes = c.bookingNotes ? (c.bookingNotes + ' · ' + notesIn) : notesIn;
  c.notes = c.bookingNotes;
  if (prestation || c.prestation) c.enfant_remarques = c.bookingNotes;
}

const prevKids = Array.isArray(c.enfants) ? c.enfants : [];
if (kidsKeyPresent) {
  // REPLACE full list (correction-safe). Keep DOB when same prenom survives.
  const prevBy = {};
  for (const e of prevKids) {
    if (e && e.prenom) prevBy[String(e.prenom).toLowerCase()] = e;
  }
  c.enfants = kids.map((n) => {
    const prev = prevBy[n.toLowerCase()];
    return {
      prenom: n,
      date_naissance: kidsDobByName[n.toLowerCase()] || (prev && prev.date_naissance) || '',
    };
  });
  c.enfantPrenoms = c.enfants.map((e) => e.prenom);
  c.enfantDobs = c.enfants.map((e) => e.date_naissance || '');
  c._enfantsReplacedAt = new Date().toISOString();
} else if (removeNames.length) {
  c.enfants = prevKids.filter((e) => e && e.prenom && !removeNames.includes(String(e.prenom).toLowerCase()));
  c.enfantPrenoms = c.enfants.map((e) => e.prenom);
  c.enfantDobs = c.enfants.map((e) => e.date_naissance || '');
} else if (kids.length) {
  // Backward-compatible merge only when enfants key absent but names passed oddly
  const by = {};
  for (const e of prevKids) {
    if (e && e.prenom) by[String(e.prenom).toLowerCase()] = e;
  }
  for (const n of kids) {
    const k = n.toLowerCase();
    if (!by[k]) by[k] = { prenom: n, date_naissance: '' };
  }
  c.enfants = Object.values(by);
  c.enfantPrenoms = c.enfants.map((e) => e.prenom);
}
const dob = toIsoDobSave(args.date_naissance || args.dob || '');
if (dob && c.enfants && c.enfants.length === 1) {
  c.enfants[0].date_naissance = dob;
  c.enfantDobs = [dob];
}
c.updatedAt = new Date().toISOString();
c._crmDirty = true;
c.enfantsCorrected = !!(kidsKeyPresent || removeNames.length || dob);
store.clients[key] = c;
try {
  const prep = $('Prep Agent Input').first().json || {};
  const ig = String(prep.igUserId || '').trim();
  const user = String(prep.instagramUsername || '').replace(/^@/, '').trim();
  if (ig && ig !== key) {
    store.clients[ig] = Object.assign({}, store.clients[ig] || {}, c, { igUserId: ig });
  }
  if (user && user !== key && !/^\d{5,}$/.test(user)) {
    c.instagramUsername = user;
    store.clients[user] = Object.assign({}, store.clients[user] || {}, c, { instagramUsername: user });
    store.clients[key] = c;
  }
} catch (eAlias) {}

return JSON.stringify({
  ok: true,
  sessionId: key,
  airtable: 'queued_for_sync',
  saved: {
    prenom: c.prenom || '',
    email: c.clientEmail || '',
    enfants: c.enfantPrenoms || [],
    prestation: c.prestation || '',
    pack: c.packName || '',
    notes: c.bookingNotes || '',
    theme: c.theme || '',
  },
});
